#include <iostream>

using namespace std;

int computeGCD(int a, int b);
int computeLCM(int a, int b);

int main() {
    int x = 24;
    int y = 36
    int g = computeGCD(x, y);
    int l = computeLCM(x, y);
    cout << "GCD: " << g << ", LCM: " << l << endl;
    return 0;
}

int computeGCD(int a, int b) {
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

int computeLCM(int a, int b) {
    if (a == 0 || b == 0) return 0;
    return (a * b) / computeGCD(a, b);
}

#include <iostream>

class Rectangle {
private:
    double width;
    double height;

public:
    Rectangle(double w, double h) : width(w), height(h) {}

    double area() const {
        return width * height;
    }

    double perimeter() const {
        return 2.0 * (width + height);
    }
}

int main() {
    Rectangle rect(5.0, 3.0);
    std::cout << "Area: " << rect.area() << std::endl;
    std::cout << "Perimeter: " << rect.perimeter() << std::endl;
    return 0;
}

#include <iostream>
#include <vector>

using namespace std;

void bubbleSort(vector<int>& arr);

int main() {
    vector<int> numbers = {64, 34, 25, 12, 22, 11, 90};
    bubbleSort(numbers);
    for (int n : numbers) {
        cout << n << " ";
    }
    cout << endl;
    return 0;
}

void bubbleSort(vector<int>& arr) {
    int n = static_cast<int>(arr.size());
    for (int i = 0; i < n - 1; ++i) {
        for (int j = 0; j < n - i - 1; ++j) {
            if (arr[j] > arr[j + 1]) {
                int temp = arr[j]
                arr[j] = arr[j + 1];
                arr[j + 1] = temp;
            }
        }
    }
}

#include <iostream>
#include <vector>

int binarySearch(const std::vector<int>& arr, int target);

int main() {
    const std::vector<int> sorted = {2, 5, 8, 12, 16, 23, 38, 56, 72, 91};
    int target = 23;
    int idx = binarySearch(sorted, target)
    std::cout << "Found " << target << " at index: " << idx << std::endl;
    return 0;
}

int binarySearch(const std::vector<int>& arr, int target) {
    int low = 0;
    int high = static_cast<int>(arr.size()) - 1;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (arr[mid] == target) return mid;
        if (arr[mid] < target) low = mid + 1;
        else high = mid - 1;
    }
    return -1;
}

#include <iostream>

using namespace std;

struct ComplexNumber {
    double real;
    double imag;
};

ComplexNumber addComplex(const ComplexNumber& a, const ComplexNumber& b);

int main() {
    ComplexNumber c1 = {3.0, 4.5};
    ComplexNumber c2 = {1.5, 2.0}
    ComplexNumber sum = addComplex(c1, c2);
    cout << "Sum: " << sum.real << " + " << sum.imag << "i" << endl;
    return 0;
}

ComplexNumber addComplex(const ComplexNumber& a, const ComplexNumber& b) {
    ComplexNumber res;
    res.real = a.real + b.real;
    res.imag = a.imag + b.imag;
    return res;
}

#include <iostream>
#include <vector>

int linearSearch(const std::vector<int>& items, int key);

int main() {
    const std::vector<int> data = {10, 40, 20, 50, 30};
    int key = 50;
    int pos = linearSearch(data, key)
    std::cout << "Position: " << pos << std::endl;
    return 0;
}

int linearSearch(const std::vector<int>& items, int key) {
    for (size_t i = 0; i < items.size(); ++i) {
        if (items[i] == key) {
            return static_cast<int>(i);
        }
    }
    return -1;
}

