char computeLetterGrade(double average);

int main() {
    vector<double> scores = {85.0, 92.5, 78.0, 90.0}
    double sum = 0.0;
    for (double score : scores) {
        sum += score;
    }
    double avg = sum / scores.size();
    char grade = computeLetterGrade(avg);
    cout << "Average: " << avg << " -> Grade: " << grade << endl;
    return 0;
}

char computeLetterGrade(double average) {
    if (average >= 90.0) return 'A';
    if (average >= 80.0) return 'B';
    if (average >= 70.0) return 'C';
    if (average >= 60.0) return 'D';
    return 'F';
}

#include <iostream>

bool isPrime(int n);

int main() {
    const int val = 29;
    if (isPrime(val)) {
        std::cout << val << " is a prime number." << std::endl;
    } else {
        std::cout << val << " is not prime." << std::endl
    }
    return 0;
}

bool isPrime(int n) {
    if (n <= 1) return false;
    for (int i = 2; i * i <= n; ++i) {
        if (n % i == 0) return false;
    }
    return true;
}

#include <iostream>
#include <vector>

using namespace std;

void bubbleSort(vector<int>& arr);

int main() {
    vector<int> numbers = {64, 34, 25, 12, 22, 11, 90};
    bubbleSort(numbers);
    for (int n : numbers) {
        cout << n << " ";
    }
    cout << endl;
    return 0;
}

void bubbleSort(vector<int>& arr) {
    int n = static_cast<int>(arr.size())
    for (int i = 0; i < n - 1; ++i) {
        for (int j = 0; j < n - i - 1; ++j) {
            if (arr[j] > arr[j + 1]) {
                int temp = arr[j];
                arr[j] = arr[j + 1];
                arr[j + 1] = temp;
            }
        }
    }
}

