long long calculateFactorial(const int n);

int main() {
    const int number = 6;
    long long fact = calculateFactorial(number);
    cout << "Factorial of " << number << " is " << fact << endl;
    return 0;
}

long long calculateFactorial(const int n) {
    long long result = 1;
    for (int i = 2; i <= n; ++i) {
        result *= i;

    return result;
}

#include <iostream>
#include <string>

using namespace std;

string reverseString(const string& input);

int main() {
    string word = "CompilerTutor";
    string rev = reverseString(word);
    cout << "Original: " << word << ", Reversed: " << rev << endl;
    return 0;


string reverseString(const string& input) {
    string output = input;
    int left = 0;
    int right = static_cast<int>(output.length()) - 1;
    while (left < right) {
        char temp = output[left];
        output[left] = output[right];
        output[right] = temp;
        left++;
        right--;
    }
    return output;
}

