}

void findMinMax(const std::vector<int>& nums, int& minVal, int& maxVal) {
    if (nums.empty()) return;
    minVal = nums[0];
    maxVal = nums[0];
    for (int val : nums) {
        if (val < minVal) minVal = val;
        if (val > maxVal) maxVal = val;
    }
}

