    cout << "Sum: " << sum.real << " + " << sum.imag << "i" << endl;
    return 0;
}

ComplexNumber addComplex(const ComplexNumber& a, const ComplexNumber& b) {
    ComplexNumber res;
    res.real = a.real + b.real;
    res.imag = a.imag + b.imag;
    return res;
}

