    int key = 50;
    int pos = linearSearch(data, key);
    std::cout << "Position: " << pos << std::endl;
    return 0;
}

int linearSearch(const std::vector<int>& items, int key) {
    for (size_t i = 0; i < items.size(); ++i) {
        if (items[i] == key) {
