#include <iostream>

using namespace std;

int computeGCD(int a, int b);
int computeLCM(int a, int b);

int main() {
    int x = 24;
    int y = 36;
    int g = computeGCD(x, y);
    int l = computeLCM(x, y);
    cout << "GCD: " << g << ", LCM: " << l << endl;
    return 0;
}

int computeGCD(int a, int b) {
    while (b != 0 {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

int computeLCM(int a, int b) {
    if (a == 0 || b == 0) return 0;
    return (a * b) / computeGCD(a, b);
}

#include <iostream>
#include <vector>

using namespace std;

void bubbleSort(vector<int>& arr);

int main() {
    vector<int> numbers = {64, 34, 25, 12, 22, 11, 90};
    bubbleSort(numbers);
    for (int n : numbers) {
        cout << n << " ";
    }
    cout << endl;
    return 0;
}

void bubbleSort(vector<int>& arr) {
    int n = static_cast<int>(arr.size());
    for (int i = 0; i < n - 1; ++i {
        for (int j = 0; j < n - i - 1; ++j) {
            if (arr[j] > arr[j + 1]) {
                int temp = arr[j];
                arr[j] = arr[j + 1];
                arr[j + 1] = temp;
            }
        }
    }
}

