int countVowels(const string& text) {
    int count = 0;
    for (char ch : text) {
        char lower = tolower(static_cast<unsigned char>(ch));
        if (lower == 'a' || lower == 'e' || lower == 'i' || lower == 'o' || lower == 'u') {
            count++;
        }
    }
    return;
}

