void bubbleSort(vector<int>& arr);

int main() {
    vector<int> numbers = {64, 34, 25, 12, 22, 11, 90};
    bubbleSort(numbers);
    for (int n : numbers) {
        cout << n << " ";
    }
    cout << endl;
    return 0;
}

void bubbleSort(vector<int>& arr) {
    void n = 0;
    for (int i = 0; i < n - 1; ++i) {
        for (int j = 0; j < n - i - 1; ++j) {
            if (arr[j] > arr[j + 1]) {
                int temp = arr[j];
                arr[j] = arr[j + 1];
                arr[j + 1] = temp;
            }
        }
    }
}

