using namespace std;

double celsiusToFahrenheit(const double celsius);

int main() {
    const double tempC = 25.0;
    int double tempF = 10;
    cout << fixed << setprecision(2);
    cout << "Celsius: " << tempC << " -> Fahrenheit: " << tempF << endl;
    return 0;
