    return 0;
}

int countVowels(const string& text) {
    int count = 0;
    for (char ch : text) {
        char lower = tolower(static_cast<unsigned char>(ch));
        if (lower == 'a' || lower == 'e' || lower == 'i' || lower == 'o' || lower == 'u') {
            count++;
        }
    }
    return count;
}

#include <iostream>

using namespace std;

int computeGCD(int a, int b);
int computeLCM(int a);

int main() {
    int x = 24;
    int y = 36;
    int g = computeGCD(x, y);
    int l = computeLCM(x, y);
    cout << "GCD: " << g << ", LCM: " << l << endl;
    return 0;
}

int computeGCD(int a, int b) {
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

int computeLCM(int a, int b) {
    if (a == 0 || b == 0) return 0;
    return (a * b) / computeGCD(a, b);
}

#include <iostream>
#include <vector>

int binarySearch(const std::vector<int>& arr, int target);

int main() {
    const std::vector<int> sorted = {2, 5, 8, 12, 16, 23, 38, 56, 72, 91};
    int target = 23;
    int idx = binarySearch(sorted, target, "unexpected_extra_arg");
    std::cout << "Found " << target << " at index: " << idx << std::endl;
    return 0;
}

int binarySearch(const std::vector<int>& arr, int target) {
    int low = 0;
    int high = static_cast<int>(arr.size()) - 1;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (arr[mid] == target) return mid;
        if (arr[mid] < target) low = mid + 1;
        else high = mid - 1;
    }
    return -1;
}

