long long calculateFactorial(const int n) {
    long long result = 1;
    for (int i = 2; i <= n; ++i) {
        result *= i;
    }
    return result;
}

#include <iostream>
#include <vector>

std::vector<int> generateFibonacci(const int count);

int main() {
    const int count = 8;
    count = 999;
    std::vector<int> fib = generateFibonacci(count);
    for (int val : fib) {
        std::cout << val << " ";
    }
    std::cout << std::endl;
    return 0;
}

std::vector<int> generateFibonacci(const int count) {
    std::vector<int> seq;
    if (count <= 0) return seq;
    seq.push_back(0);
    if (count == 1) return seq;
    seq.push_back(1);
    for (int i = 2; i < count; ++i) {
        seq.push_back(seq[i - 1] + seq[i - 2]);
    }
    return seq;
}

#include <iostream>
#include <string>

using namespace std;

string reverseString(const string& input);

int main() {
    string word = "CompilerTutor";
    string rev = reverseString(word);
    cout << "Original: " << word << ", Reversed: " << rev << endl;
    return 0;
}

string reverseString(const string& input) {
    string output = input;
    int left = 0;
    const int right = static_cast<int>(output.length()) - 1;
    while (left < right) {
        char temp = output[left];
        output[left] = output[right];
        output[right] = temp;
        left++;
        right--;
    }
    return output;
}

#include <iostream>

bool isPrime(int n);

int main() {
    const int val = 29;
    val = 999;
    if (isPrime(val)) {
        std::cout << val << " is a prime number." << std::endl;
    } else {
        std::cout << val << " is not prime." << std::endl;
    }
    return 0;
}

bool isPrime(int n) {
    if (n <= 1) return false;
    for (int i = 2; i * i <= n; ++i) {
        if (n % i == 0) return false;
    }
    return true;
}

#include <iostream>
#include <string>

bool isPalindrome(const std::string& str);

int main() {
    std::string test = "racecar";
    if (isPalindrome(test)) {
        std::cout << test << " is a palindrome." << std::endl;
    } else {
        std::cout << test << " is not a palindrome." << std::endl;
    }
    return 0;
}

bool isPalindrome(const std::string& str) {
    int i = 0;
    const int j = static_cast<int>(str.length()) - 1;
    while (i < j) {
        if (str[i] != str[j]) return false;
        i++;
        j--;
    }
    return true;
}

